import numpy as np, torch, model, itertools
net = model.load(); neg = model.negatives()
rows=[0,14,5]; others=[i for i in range(16) if i not in rows]
L='blocks.2.act'
def bad(a):
    m=np.zeros(len(a),bool)
    for i in rows: m|=np.asarray(model.in_basin(i,a))
    return m
def oth(a): return np.mean([np.asarray(model.in_basin(i,a)).mean() for i in others])
# training data
torch.manual_seed(5)
ct=torch.rand(12000); xt=torch.randn(12000,2)
at,St,Ac=model.decode(net,xt,ct,save_states=True,capture=(L,))
yt=torch.tensor(bad(at),dtype=torch.float32); print('train bad',yt.mean().item(),flush=True)
H=Ac[L]  # (20,B,128)
res_probe={}
for LO,HI in [(6,12),(8,14),(10,16)]:
    X=H[LO:HI].reshape(-1,128); Y=yt.repeat(HI-LO)
    mu=X.mean(0); 
    w=torch.zeros(128,requires_grad=True); b=torch.zeros(1,requires_grad=True)
    opt=torch.optim.Adam([w,b],lr=0.05)
    pw=torch.tensor(3.0)
    for it in range(400):
        opt.zero_grad(); l=torch.nn.functional.binary_cross_entropy_with_logits(X@w+b,Y,pos_weight=pw)+1e-4*(w**2).sum(); l.backward(); opt.step()
    res_probe[(LO,HI)]=(w.detach().clone(),b.detach().clone())
    s=(X@w+b).detach()
    for thr in [0,1,2,3]:
        f=s>thr; print(LO,HI,'thr',thr,'recall',round((f&(Y>0)).sum().item()/Y.sum().item(),3),'fp_rate',round((f&(Y==0)).sum().item()/(Y==0).sum().item(),4),flush=True)
torch.save(res_probe,'probes.pt')
# eval set
torch.manual_seed(3); NC=16; per=384
cs=torch.tensor(np.repeat(np.linspace(0.03,0.97,NC),per),dtype=torch.float32); xi=torch.randn(len(cs),2)
a0,S,_=model.decode(net,xi,cs,save_states=True); A0=a0.numpy(); b0=bad(a0); o0=oth(a0)
cid=np.repeat(np.arange(NC),per); Pc=[torch.tensor(A0[(cid==j)&~b0]) for j in range(NC)]
def offd(a):
    off=0
    for j in range(NC):
        m=cid==j; d=torch.cdist(torch.tensor(a[m]),Pc[j]).min(1).values.numpy(); off+=(d>0.35).sum()
    return off/len(a)
off0=offd(A0); print('bad0',round(b0.mean(),4),flush=True)
@torch.no_grad()
def run(LO,HI,thr,uang,mag):
    w,b=res_probe[(LO,HI)]; u=np.array([np.cos(np.radians(uang)),np.sin(np.radians(uang))])
    x=S[LO].clone(); d=torch.tensor(-mag*u,dtype=torch.float32)
    for k in range(LO,20):
        t=torch.full((len(x),),1-k/20); v,ac=net.velocity(x,t,cs,capture=(L,),count=False)
        if k<HI:
            f=(ac[L]@w+b)>thr; v=v+f.float()[:,None]*d
        x=x-v/20
    return x.numpy()
res=[]
for (LO,HI),thr,uang,mag in itertools.product([(6,12),(8,14),(10,16)],[1,2,3],[90,180,135],[10,20]):
    a1=run(LO,HI,thr,uang,mag); b1=bad(a1)
    mv=(np.linalg.norm(a1-A0,axis=1)>0.3)&~b0
    res.append((round(b0.mean()-b1.mean(),4),round(mv.mean(),4),round(offd(a1)-off0,4),round(oth(a1)-o0,4),LO,HI,thr,uang,mag))
res.sort(key=lambda r:-(r[0]-1.5*r[1]-2*max(r[2],0)-2*max(r[3],0)))
