import numpy as np, torch, model
from scipy.spatial import cKDTree
net = model.load()
lp=torch.tensor(np.load('labelprobe.npy')); w0=lp[:128]; b0=lp[128]
W=torch.tensor(np.load('probe9_11.npy')); B=torch.tensor(np.load('probe9_11_b.npy'))
R90=torch.tensor([[0.,-1.],[1.,0.]])
def run(xi,c,pf=None,lo=9,hi=12):
    n=xi.shape[0]; x=xi.clone(); s13=None
    with torch.no_grad():
      for k in range(20):
        t=torch.full((n,),1-k/20)
        v,a=net.velocity(x,t,c,("blocks.2.act",),count=False); A=a["blocks.2.act"]
        if k==13: s13=(A@w0+b0)>0
        if pf is not None and lo<=k<hi:
            f=(A@W+B)>0; v=v+f[:,None].float()*pf(x)
        x=x-v/20
    return x.numpy(), s13.numpy()
torch.manual_seed(7)
xr=torch.randn(24000,2); cr=torch.rand(24000); ref,Lr=run(xr,cr); des=ref[~Lr]; cd=cr.numpy()[~Lr]
tree=cKDTree(np.c_[ref,4*cr.numpy()])
N=6000; xi=torch.randn(N,2); c=torch.rand(N); cn=c.numpy()
def ed(X,Y):
    X=torch.tensor(X);Y=torch.tensor(Y)
    return (2*torch.cdist(X,Y).mean()-torch.cdist(X,X).mean()-torch.cdist(Y,Y).mean()).item()
def score(a):
    e=np.mean([ed(a[(cn>=l)&(cn<l+.1)], des[(cd>=l)&(cd<l+.1)][:1500]) for l in np.arange(0,1,.1)])
    d=tree.query(np.c_[a,4*cn])[0]
    return round(e,4), round((d>0.2).mean(),4), round((d>0.35).mean(),4)
a0,_=run(xi,c); print('base',score(a0))
def const(d,D):
    u=torch.tensor([np.cos(np.radians(d)),np.sin(np.radians(d))],dtype=torch.float32); return lambda x: -20*D/3*u[None]
def rot(th): return lambda x: -20*th/3*(x@R90.T)
cands={'c45_2.5':const(45,2.5),'c67_2.5':const(67,2.5),'c90_2.5':const(90,2.5),'c45_1.5':const(45,1.5),
       'ccw0.5':rot(0.5),'ccw0.8':rot(0.8),'ccw1.1':rot(1.1),'cw0.5':rot(-0.5),'cw0.8':rot(-0.8),'cw1.1':rot(-1.1)}
for nm,pf in cands.items():
    a1,_=run(xi,c,pf); print(nm,score(a1))
